def get_func_in_mro(obj: Any, code: CodeType) -> Optional[Callable[..., Any]]:
    val = inspect.getattr_static(obj, code.co_name, None)
    if val is None:
        return None
    if isinstance(val, (classmethod, staticmethod)):
        val = val.__func__
    elif isinstance(val, property):
        val = val.fget
    if _has_code(val, code):
        return val
    return None


def _has_code(func: Optional[Callable[..., Any]], code: CodeType) -> Optional[Callable[..., Any]]:
    if func is None:
        return None
    func_code = getattr(func, '__code__', None)
    if func_code is code:
        return func
    return None


def get_func(frame: FrameType) -> Optional[Callable[..., Any]]:
    code = frame.f_code
    if code.co_name is None:
        return None
    for name in ('self', 'cls'):
        if name in frame.f_locals:
            obj = frame.f_locals[name]
            func = get_func_in_mro(obj, code)
            if func is not None:
                return func
            func = get_func_in_mro(type(obj), code)
            if func is not None:
                return func
    for val in get_locals_from_previous_frames(frame.f_back):
        func = _has_code(val, code)
        if func is not None:
            return func
        if inspect.isclass(val):
            func = get_func_in_mro(val, code)
            if func is not None:
                return func
    return None


